// Convierte las filas de cada pestaña al formato de las tablas de promos
function fecha(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return new Date(Date.UTC(1899, 11, 30) + v * 864e5).toISOString().slice(0, 10);
  const s = String(v).trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  const m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/);
  if (m) { const y = m[3].length === 2 ? '20' + m[3] : m[3]; return `${y}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`; }
  return null;
}
const texto = (v) => (v === null || v === undefined || String(v).trim() === '') ? null : String(v).trim();
const numero = (v) => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v).replace(/[^\d.\-]/g, ''));
  return isNaN(n) ? null : n;
};
const siNo = (v) => {
  const s = String(v ?? '').trim().toLowerCase();
  if (s === '') return true;
  return ['si', 'sí', 'true', '1', 'x', 'activa', 'yes'].includes(s);
};
const slug = (s) => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60);
const adIds = (v) => {
  if (v === null || v === undefined || v === '') return [];
  if (typeof v === 'number') return [BigInt(Math.round(v)).toString()];
  return String(v).split(/[\s,;|]+/).map(x => x.replace(/\D/g, '')).filter(Boolean);
};

// Una pestaña por agencia; la fila 1 de cada pestaña son los encabezados
const AGENCIAS = { 'Rs Independencia': 'independencia', 'Rs Centro': 'centro', 'Rs Periodismo': 'periodismo', 'Rs Matriz': 'matriz' };
const salida = [];
for (const rango of $input.first().json.valueRanges || []) {
  const pestana = rango.range.split('!')[0].replace(/^'|'$/g, '');
  const agencia = AGENCIAS[pestana];
  if (!agencia) continue;
  const valores = rango.values || [];
  const encabezados = (valores[0] || []).map(h => String(h).trim().toLowerCase().replace(/\s+/g, '_'));
  const filas = valores.slice(1).map(fila => Object.fromEntries(encabezados.map((h, i) => [h, fila[i] ?? ''])));

  const vistos = new Set();
  const promos = [];
  for (const r of filas) {
  const titulo = texto(r.titulo);
  if (!titulo) continue;
  let id = texto(r.id) ? slug(r.id) : slug(titulo);
  if (vistos.has(id)) id = `${id}-${vistos.size + 1}`;
  vistos.add(id);
  promos.push({
    id, activa: siNo(r.activa), titulo,
    destino: texto(r.destino), hotel: texto(r.hotel), ad_ids: adIds(r.ad_ids ?? r.ad_id),
    vigencia_desde: fecha(r.vigencia_desde), vigencia_hasta: fecha(r.vigencia_hasta),
    viaje_desde: fecha(r.viaje_desde), viaje_hasta: fecha(r.viaje_hasta),
    noches: numero(r.noches) === null ? null : Math.round(numero(r.noches)),
    plan: texto(r.plan), dias_aplica: texto(r.dias_aplica), precio_desde: numero(r.precio_desde),
    precio_detalle: texto(r.precio_detalle), precios_menores: texto(r.precios_menores),
    incluye: texto(r.incluye), no_incluye: texto(r.no_incluye), condiciones: texto(r.condiciones),
    descripcion: texto(r.descripcion), imagen_url: texto(r.imagen_url)
  });
}
  salida.push({ json: { agencia, promos } });
}
return salida;

